// === Tab: mySketch ===
var pos = [];
var rangeMax=150.;
var drawPoint=true, drawLine=true; //set false to hide it
var parNumb=150, vel;
var slider, slider1, button;
let fontsize = 40;

function setup() {
	blendMode(ADD);
  createCanvas(1920, 1080);
  smooth(8);

	slider = createSlider(0, 350, 200, 10);
  slider.position(10, 10);
  slider.style('width', '100px');

	slider1 = createSlider(.1, 20, 4, .5);
  slider1.position(120, 10);
  slider1.style('width', '100px');

	button = createButton('particle');
  button.position(10, 50);
  button.mousePressed(showHideParticle);

	button = createButton('line');
  button.position(10, 75);
  button.mousePressed(showHideLine);

  // creating points loop
  for (var i=0; i<parNumb; i+=1) {
    var momPos = createVector();
    momPos.x=random(width);
    momPos.y=random(height);
    pos.push(momPos);
  }
}

function draw() {
	rangeMax = slider.value();
  background(0);


  if (drawPoint) {
    stroke(0, 75, 255);
    strokeWeight(5);
    for (var i=0; i<pos.length; i+=1) {
      point(pos[i].x, pos[i].y);
    }
  }

  if (drawLine) {
    stroke(150, 30);
		strokeWeight(1);
    for (var i=0; i<pos.length; i+=1) {
      for (var y=1; y<pos.length; y+=1) {
        if (pos[i].dist(pos[y])<rangeMax) {
          line(pos[i].x, pos[i].y, pos[y].x, pos[y].y);
        }
      }
    }
  }
  bounds();
  movePos();
	fill(255);
	textAlign(LEFT);
	text(slider.value()+' rangeMax', 10, 45);
	text(slider1.value()+' velocity', 120, 45);
}

function movePos() {
	vel = slider1.value();
  for (var i=0; i<pos.length; i+=1) {
    //var jit = createVector(sin(frameCount*i*0.0004)*vel, sin(frameCount*i*0.0006)*vel); // sin movement
		var jit = createVector((noise(frameCount*i*0.0003)*vel, sin(frameCount*i*0.0007)-.5)*vel, (noise(frameCount*i*0.0005)*vel, sin(frameCount*i*0.0008)-.5)*vel); //noise movement
    pos[i].add(jit);
  }
}

function bounds() {
  for (var i=0; i<pos.length; i+=1) {
    if (pos[i].x>width) pos[i].x=0;
    if (pos[i].x<0) pos[i].x=width;
    if (pos[i].y>height) pos[i].y=0;
    if (pos[i].y<0) pos[i].y=height;
  }
}

function showHideParticle() {
	drawPoint=!drawPoint;
}

function showHideLine() {
	drawLine=!drawLine;
}

